// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IPowerAsset {
    function mintRegistrationRewards(
        address userAddr,
        address registrationNode
    ) external;
}

contract AccountRegistrarV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;

    bytes32 private constant _REGISTRATION_TYPEHASH =
        keccak256(
            "Registration(address userAddr,bytes32 emailHash,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    IPowerAsset public powerAsset;

    mapping(address => bytes32) public userEmailHash;
    mapping(bytes32 => address) public emailHashToAddr;
    mapping(address => uint256) public nonces;
    mapping(address => address) public referral;

    event UserRegistered(
        address indexed user,
        address indexed referer,
        bytes32 emailHash
    );

    function initialize(address _powerAssetAddr) public virtual initializer {
        __Ownable_init(msg.sender);
        __EIP712_init("Aiverse-Account-Registrar", "1");
        __Pausable_init();
        __ReentrancyGuard_init();

        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setPowerAsset(address _powerAssetAddr) external onlyOwner {
        require(_powerAssetAddr != address(0), "Invalid PowerAsset address");
        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function registerByEmail(
        address userAddr,
        address refererAddr,
        bytes32 emailHash,
        bytes memory ownerSignature,
        bytes memory userSignature,
        uint256 expireAt
    ) external onlyOwner nonReentrant whenNotPaused {
        require(emailHash != bytes32(0), "Invalid email hash");
        require(userAddr != address(0), "Invalid user address");
        require(refererAddr != address(0), "Invalid referer address");
        require(refererAddr != userAddr, "Self referral not allowed");

        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        require(userEmailHash[refererAddr] != bytes32(0), "Invalid referer");
        require(
            emailHashToAddr[emailHash] == address(0),
            "Email already registered"
        );
        require(
            userEmailHash[userAddr] == bytes32(0),
            "Address already registered"
        );

        _verifySignature(
            userAddr,
            emailHash,
            ownerSignature,
            owner(),
            expireAt
        );
        _verifySignature(
            userAddr,
            emailHash,
            userSignature,
            userAddr,
            expireAt
        );

        _register(userAddr, emailHash, refererAddr);
    }

    function _verifySignature(
        address userAddr,
        bytes32 emailHash,
        bytes memory signature,
        address expectedSigner,
        uint256 expireAt
    ) internal view {
        bytes32 structHash = keccak256(
            abi.encode(
                _REGISTRATION_TYPEHASH,
                userAddr,
                emailHash,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(signature);
        require(recovered == expectedSigner, "Invalid signature");
    }

    function _register(
        address userAddr,
        bytes32 emailHash,
        address refererAddr
    ) internal {
        nonces[userAddr]++;
        userEmailHash[userAddr] = emailHash;
        emailHashToAddr[emailHash] = userAddr;
        referral[userAddr] = refererAddr;
        powerAsset.mintRegistrationRewards(userAddr, msg.sender);
        emit UserRegistered(userAddr, refererAddr, emailHash);
    }
}

contracts/V1.0.3/AiverseCoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract AiverseCoinV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable
{
    uint256 public constant HALVING_PERIOD_DAYS = 1460;
    uint256 public constant MAX_TOTAL_SUPPLY = 210_000_000_000 ether;

    uint256 public initialDailyReward;
    uint256 public startDay;
    address public stakeController;
    uint256 public lastMintedDay;

    function initialize(
        string memory name_,
        string memory symbol_
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ERC20_init(name_, symbol_);
        __ReentrancyGuard_init();
        startDay = block.timestamp / 1 days;
        initialDailyReward = (MAX_TOTAL_SUPPLY / 2) / HALVING_PERIOD_DAYS;
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setStakeController(
        address _stakeController
    ) external onlyOwner whenNotPaused {
        require(
            _stakeController != address(0),
            "Invalid stake controller address"
        );
        stakeController = _stakeController;
    }

    function mintToken() external nonReentrant whenNotPaused {
        require(msg.sender == stakeController, "Only StakeController can mint");
        uint256 currentDay = block.timestamp / 1 days;
        require(currentDay > lastMintedDay, "Already minted for today");

        uint256 amount = getMintAmountByDay(currentDay);
        require(
            totalSupply() + amount <= MAX_TOTAL_SUPPLY,
            "Exceeds max supply"
        );

        lastMintedDay = currentDay;
        _mint(address(this), amount);
    }

    function userClaimToken(
        address userAddr,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        require(
            msg.sender == stakeController,
            "Only StakeController can transfer"
        );
        _transfer(address(this), userAddr, amount);
    }

    function getMintAmountByDay(uint256 day) public view returns (uint256) {
        require(day >= startDay, "Invalid day");

        uint256 daysSinceStart = day - startDay;
        uint256 halvingEra = daysSinceStart / HALVING_PERIOD_DAYS;

        uint256 reward = initialDailyReward >> halvingEra;
        return reward;
    }
}

contracts/V1.0.3/AiverseFund.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

struct GenesisSeat {
    uint32 seatNo;
    uint64 paidAt;
    uint128 usdcPaid;
}

struct GenesisVesting {
    uint64 purchaseTime;
    uint64 firstClaimableAt;
    uint8 claimedPeriodsCount;
    uint8 delayPeriods;
}

contract AiverseFundV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;

    IERC20 public aicoin;
    IERC20 public usdc;

    uint256 public minPurchaseAmount;
    uint256 public price;

    address public fundAddress;
    address public executorAddress;

    uint256 public totalSold;
    uint256 public totalUSDCReceived;

    uint256 public seatsFilled;
    mapping(address => GenesisSeat) public seatOf;
    mapping(address => GenesisVesting) public vestingOf;

    uint64 public globalFirstReleaseAt;

    uint256 public baseSeatPriceUsdc;

    uint256 public maxSeats;

    mapping(address => uint64) public lastVestingDelayBumpAt;

    uint256 public constant GENESIS_PERIODS = 12;
    uint256 public constant GENESIS_BATCH_SIZE = 10;
    uint256 public constant GENESIS_PERIOD_DURATION = 30 days;

    event FundAddressUpdated(
        address indexed oldAddress,
        address indexed newAddress
    );
    event ExecutorAddressUpdated(
        address indexed oldAddress,
        address indexed newAddress
    );
    event USDCWithdrawn(address indexed to, uint256 amount);
    event AICOINDeposited(address indexed from, uint256 amount);

    event GenesisSeatPurchased(
        address indexed buyer,
        uint256 seatNo,
        uint256 usdcAmount,
        uint256 totalAicoinScheduled,
        uint256 timestamp
    );
    event GenesisClaimed(address indexed user, uint256 amount);
    event GlobalFirstReleaseUpdated(uint64 oldTs, uint64 newTs);
    event BaseSeatPriceUsdcUpdated(uint256 oldPrice, uint256 newPrice);
    event MaxSeatsUpdated(uint256 oldMax, uint256 newMax);
    event VestingDelayIncreased(address indexed user, uint8 newDelayPeriods);

    modifier onlyOwnerOrExecutor() {
        require(
            msg.sender == owner() || msg.sender == executorAddress,
            "Not owner or executor"
        );
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _aicoinAddr,
        address _usdcAddr,
        uint256 _minPurchaseAmount,
        uint256 _price
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();

        require(_aicoinAddr != address(0), "Invalid AICOIN address");
        require(_usdcAddr != address(0), "Invalid USDC address");
        require(
            _minPurchaseAmount > 0,
            "Min purchase amount must be greater than 0"
        );
        require(_price > 0, "Price must be greater than 0");

        aicoin = IERC20(_aicoinAddr);
        usdc = IERC20(_usdcAddr);
        minPurchaseAmount = _minPurchaseAmount;
        price = _price;
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setFundAddress(address _fundAddress) external onlyOwner {
        require(_fundAddress != address(0), "Invalid fund address");
        address oldAddress = fundAddress;
        fundAddress = _fundAddress;
        emit FundAddressUpdated(oldAddress, _fundAddress);
    }

    function setExecutorAddress(address _executorAddress) external onlyOwner {
        address oldAddress = executorAddress;
        executorAddress = _executorAddress;
        emit ExecutorAddressUpdated(oldAddress, _executorAddress);
    }

    function setGlobalFirstReleaseAt(uint64 newTs) external onlyOwner {
        require(newTs >= block.timestamp, "T0 must not be in the past");
        require(seatsFilled == 0, "Cannot change T0 after seats sold");
        uint64 oldTs = globalFirstReleaseAt;
        globalFirstReleaseAt = newTs;
        emit GlobalFirstReleaseUpdated(oldTs, newTs);
    }

    function setBaseSeatPriceUsdc(uint256 newPrice) external onlyOwner {
        require(newPrice > 0, "Invalid base price");
        require(seatsFilled == 0, "Cannot change price after seats sold");
        uint256 oldPrice = baseSeatPriceUsdc;
        baseSeatPriceUsdc = newPrice;
        emit BaseSeatPriceUsdcUpdated(oldPrice, newPrice);
    }

    function setMaxSeats(uint256 newMax) external onlyOwner {
        require(newMax >= seatsFilled, "Below seats sold");
        uint256 oldMax = maxSeats;
        maxSeats = newMax;
        emit MaxSeatsUpdated(oldMax, newMax);
    }

    function increaseVestingDelay(address user) external onlyOwner {
        require(user != address(0), "Invalid user");
        GenesisVesting storage v = vestingOf[user];
        require(v.firstClaimableAt > 0, "No vesting");
        uint64 lastBump = lastVestingDelayBumpAt[user];
        if (lastBump != 0) {
            require(
                block.timestamp >= uint256(lastBump) + GENESIS_PERIOD_DURATION,
                "delay bump cooldown"
            );
        }
        require(v.delayPeriods < type(uint8).max, "delay overflow");
        unchecked {
            v.delayPeriods += 1;
        }
        lastVestingDelayBumpAt[user] = uint64(block.timestamp);
        emit VestingDelayIncreased(user, v.delayPeriods);
    }

    function depositAICOIN(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be greater than 0");
        aicoin.safeTransferFrom(msg.sender, address(this), amount);
        emit AICOINDeposited(msg.sender, amount);
    }

    function withdrawUSDC() external onlyOwner nonReentrant {
        uint256 balance = usdc.balanceOf(address(this));
        require(balance > 0, "No USDC to withdraw");
        usdc.safeTransfer(msg.sender, balance);
        emit USDCWithdrawn(msg.sender, balance);
    }

    function emergencyWithdrawToken(
        address tokenAddress
    ) external onlyOwner nonReentrant {
        require(tokenAddress != address(0), "Invalid token address");
        require(
            tokenAddress != address(aicoin),
            "AICOIN locked: vesting claims only"
        );
        IERC20 token = IERC20(tokenAddress);
        uint256 balance = token.balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");
        token.safeTransfer(msg.sender, balance);
    }

    function getAICOINBalance() public view returns (uint256) {
        return aicoin.balanceOf(address(this));
    }

    function getUSDCBalance() public view returns (uint256) {
        return usdc.balanceOf(address(this));
    }

    function currentSeatPrice() public view returns (uint256) {
        uint256 batch = seatsFilled / GENESIS_BATCH_SIZE;
        require(baseSeatPriceUsdc > 0, "Base seat price not set");
        return (baseSeatPriceUsdc * _batchMultiplier(batch)) / 1e16;
    }

    function aicoinTotalForSeatNo(
        uint256 seatNo
    ) public pure returns (uint256) {
        if (seatNo == 1) return 150_000_000 * 1e18;
        if (seatNo == 2) return 140_000_000 * 1e18;
        if (seatNo == 3) return 130_000_000 * 1e18;
        if (seatNo >= 4 && seatNo <= 10) return 110_000_000 * 1e18;
        return 100_000_000 * 1e18;
    }

    function paySeat() external nonReentrant whenNotPaused {
        require(fundAddress != address(0), "Fund address not set");
        uint256 seatPrice = currentSeatPrice();
        _paySeat(msg.sender, seatPrice);
    }

    function paySeatWithPermit(
        address buyer,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant whenNotPaused onlyOwnerOrExecutor {
        require(fundAddress != address(0), "Fund address not set");
        require(buyer != address(0), "Invalid buyer");
        uint256 seatPrice = currentSeatPrice();
        require(deadline >= block.timestamp, "Permit expired");

        IERC20Permit(address(usdc)).permit(
            buyer,
            address(this),
            seatPrice,
            deadline,
            v,
            r,
            s
        );
        _paySeat(buyer, seatPrice);
    }

    function globalUnlockTime(uint8 period) public view returns (uint256) {
        require(period < GENESIS_PERIODS, "Invalid period");
        require(globalFirstReleaseAt > 0, "T0 not set");
        return
            uint256(globalFirstReleaseAt) +
            uint256(period) *
            GENESIS_PERIOD_DURATION;
    }

    function trancheAmount(
        uint128 total,
        uint8 period
    ) public pure returns (uint128) {
        require(period < GENESIS_PERIODS, "Invalid period");
        uint256 t = uint256(total);
        uint256 base = t / GENESIS_PERIODS;
        if (uint256(period) == GENESIS_PERIODS - 1) {
            return uint128(t - base * (GENESIS_PERIODS - 1));
        }
        return uint128(base);
    }

    function claimable(address user) public view returns (uint256) {
        GenesisVesting storage v = vestingOf[user];
        if (v.firstClaimableAt == 0) return 0;
        uint128 total = _vestingTotalAicoin(user);
        (uint256 sum, ) = _sumUnlockedTranches(
            v.firstClaimableAt,
            v.delayPeriods,
            v.claimedPeriodsCount,
            total
        );
        return sum;
    }

    function claim() external nonReentrant whenNotPaused {
        _claimVesting(msg.sender);
    }

    function claimFor(
        address user
    ) external nonReentrant whenNotPaused onlyOwnerOrExecutor {
        require(user != address(0), "Invalid user");
        _claimVesting(user);
    }

    function _paySeat(address buyer, uint256 usdcAmount) internal {
        require(maxSeats > 0, "Max seats not set");
        require(seatsFilled < maxSeats, "Sold out");
        require(seatOf[buyer].seatNo == 0, "Already purchased");
        require(usdcAmount > 0, "Invalid USDC amount");
        require(globalFirstReleaseAt > 0, "T0 not set");

        uint256 seatNo = seatsFilled + 1;
        uint256 totalReward = aicoinTotalForSeatNo(seatNo);
        require(totalReward <= type(uint128).max, "Reward too large");
        require(
            aicoin.balanceOf(address(this)) >= totalReward,
            "Insufficient AICOIN in contract"
        );

        seatsFilled = seatNo;
        totalUSDCReceived += usdcAmount;

        seatOf[buyer] = GenesisSeat({
            seatNo: uint32(seatNo),
            paidAt: uint64(block.timestamp),
            usdcPaid: uint128(usdcAmount)
        });

        vestingOf[buyer] = GenesisVesting({
            purchaseTime: uint64(block.timestamp),
            firstClaimableAt: _firstClaimableAtForPurchase(
                block.timestamp,
                globalFirstReleaseAt
            ),
            claimedPeriodsCount: 0,
            delayPeriods: 0
        });

        emit GenesisSeatPurchased(
            buyer,
            seatNo,
            usdcAmount,
            totalReward,
            block.timestamp
        );

        usdc.safeTransferFrom(buyer, fundAddress, usdcAmount);
    }

    function _firstClaimableAtForPurchase(
        uint256 purchaseTs,
        uint64 t0
    ) internal pure returns (uint64) {
        uint256 t0u = uint256(t0);
        if (purchaseTs < t0u) {
            uint256 timeToT0 = t0u - purchaseTs;
            if (timeToT0 > GENESIS_PERIOD_DURATION) {
                return t0;
            }
            uint256 firstAtEarly = t0u + GENESIS_PERIOD_DURATION;
            require(firstAtEarly <= type(uint64).max, "first claim overflow");
            return uint64(firstAtEarly);
        }
        uint256 currentPeriod = (purchaseTs - t0u) / GENESIS_PERIOD_DURATION;
        uint256 firstGlobalPeriod = currentPeriod + 2;
        uint256 firstAt = t0u + firstGlobalPeriod * GENESIS_PERIOD_DURATION;
        require(firstAt <= type(uint64).max, "first claim overflow");
        return uint64(firstAt);
    }

    function _isPeriodUnlocked(
        uint64 firstAt,
        uint8 delayPeriods,
        uint8 p
    ) internal view returns (bool) {
        if (firstAt == 0) return false;
        return
            block.timestamp >=
            uint256(firstAt) +
                (uint256(delayPeriods) + uint256(p)) *
                GENESIS_PERIOD_DURATION;
    }

    function _vestingTotalAicoin(address user) internal view returns (uint128) {
        uint32 seatNo = seatOf[user].seatNo;
        require(seatNo > 0, "No seat");
        uint256 t = aicoinTotalForSeatNo(uint256(seatNo));
        require(t <= type(uint128).max, "total");
        return uint128(t);
    }

    function _sumUnlockedTranches(
        uint64 firstClaimableAt,
        uint8 delayPeriods,
        uint8 startPeriod,
        uint128 totalAicoin
    ) internal view returns (uint256 amount, uint8 nextPeriod) {
        uint8 p = startPeriod;
        uint256 sum = 0;
        for (; p < uint8(GENESIS_PERIODS); ) {
            if (!_isPeriodUnlocked(firstClaimableAt, delayPeriods, p)) {
                break;
            }
            sum += trancheAmount(totalAicoin, p);
            unchecked {
                ++p;
            }
        }
        return (sum, p);
    }

    function _claimVesting(address user) internal {
        GenesisVesting storage v = vestingOf[user];
        require(v.firstClaimableAt > 0, "No vesting");

        uint128 total = _vestingTotalAicoin(user);
        (uint256 sum, uint8 nextPeriod) = _sumUnlockedTranches(
            v.firstClaimableAt,
            v.delayPeriods,
            v.claimedPeriodsCount,
            total
        );

        require(sum > 0, "Nothing to claim");
        v.claimedPeriodsCount = nextPeriod;
        require(aicoin.balanceOf(address(this)) >= sum, "Insufficient AICOIN");
        aicoin.safeTransfer(user, sum);
        emit GenesisClaimed(user, sum);
    }

    function _batchMultiplier(uint256 batch) internal pure returns (uint256) {
        if (batch == 0) return 10_000_000_000_000_000;
        if (batch == 1) return 11_000_000_000_000_000;
        if (batch == 2) return 12_100_000_000_000_000;
        if (batch == 3) return 13_310_000_000_000_000;
        if (batch == 4) return 14_641_000_000_000_000;
        if (batch == 5) return 16_105_100_000_000_000;
        if (batch == 6) return 17_715_610_000_000_000;
        if (batch == 7) return 19_487_171_000_000_000;
        if (batch == 8) return 21_435_888_100_000_000;
        if (batch == 9) return 23_579_476_910_000_000;
        if (batch == 10) return 25_937_424_601_000_000;
        if (batch == 11) return 28_531_167_061_100_000;
        if (batch == 12) return 31_384_283_767_210_000;
        if (batch == 13) return 34_522_712_143_931_000;
        if (batch == 14) return 37_974_983_358_324_100;
        if (batch == 15) return 41_772_481_694_156_510;
        if (batch == 16) return 45_949_729_863_572_161;
        revert("Invalid batch");
    }

    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    fallback() external payable {
        revert("Fallback not allowed");
    }
}

contracts/V1.0.3/CheckInManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IAccountRegistrar {
    function userEmailHash(address user) external view returns (bytes32);
}

interface IPowerAsset {
    function mintCheckInRewards(
        address user,
        address checkInNode,
        address verifierNode
    ) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function getNodeList() external view returns (address[] memory);
}

contract CheckInManagerV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    INodeManager public nodeManager;
    IAccountRegistrar public accountRegistrar;
    IPowerAsset public powerAsset;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _CHECKIN_TYPEHASH =
        keccak256(
            "CheckIn(address userAddr,address checkInNode,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    mapping(address => uint256) public nonces;
    mapping(address => mapping(uint256 => bool)) public checkedIn;
    mapping(address => mapping(uint256 => address)) public verifierNodeForDay;

    event VerifierNodeSelected(
        address indexed userAddr,
        address indexed verifierNode,
        uint256 indexed day
    );
    event CheckedIn(
        address indexed userAddr,
        address indexed checkInNode,
        address indexed verifierNode,
        uint256 day
    );

    function initialize(
        address _nodeManagerAddr,
        address _registrarAddr,
        address _powerAssetAddr
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-CheckIn-Manager", "1");
        __ReentrancyGuard_init();

        nodeManager = INodeManager(_nodeManagerAddr);
        accountRegistrar = IAccountRegistrar(_registrarAddr);
        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function selectRandomVerifierNode(
        address userAddr
    ) external nonReentrant whenNotPaused returns (address) {
        require(userAddr != address(0), "Invalid user address");

        _checkIsNode(msg.sender);
        address[] memory nodeListArray = nodeManager.getNodeList();
        require(nodeListArray.length > 1, "Not enough nodes");

        uint256 today = _getToday();
        require(
            verifierNodeForDay[userAddr][today] == address(0),
            "Already selected today"
        );

        uint256 randomSeed = uint256(
            keccak256(
                abi.encodePacked(
                    blockhash(block.number - 1) != bytes32(0)
                        ? blockhash(block.number - 1)
                        : blockhash(block.number - 2),
                    block.prevrandao,
                    block.timestamp,
                    userAddr,
                    nonces[userAddr]
                )
            )
        );

        uint256 startIndex = randomSeed % nodeListArray.length;

        address verifierNode;
        for (uint256 i = 0; i < nodeListArray.length; i++) {
            uint256 idx = (startIndex + i) % nodeListArray.length;
            if (nodeListArray[idx] != msg.sender) {
                verifierNode = nodeListArray[idx];
                break;
            }
        }

        verifierNodeForDay[userAddr][today] = verifierNode;
        emit VerifierNodeSelected(userAddr, verifierNode, today);
        return verifierNode;
    }

    function checkIn(
        address userAddr,
        address checkInNode,
        uint256 expireAt,
        bytes memory userSig,
        bytes memory checkInNodeSig
    ) external nonReentrant whenNotPaused {
        require(userAddr != address(0), "Invalid user address");

        _checkIsNode(msg.sender);
        _checkIsNode(checkInNode);
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        uint256 today = _getToday();
        require(
            accountRegistrar.userEmailHash(userAddr) != bytes32(0),
            "User not registered"
        );
        require(!checkedIn[userAddr][today], "Already checked today");

        address verifierNode = verifierNodeForDay[userAddr][today];
        require(verifierNode == msg.sender, "Non-designated verifier node");

        bytes32 structHash = keccak256(
            abi.encode(
                _CHECKIN_TYPEHASH,
                userAddr,
                checkInNode,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);

        address recoveredUser = digest.recover(userSig);
        require(recoveredUser == userAddr, "Invalid user signature");

        address recoveredCheckInNode = digest.recover(checkInNodeSig);
        require(
            recoveredCheckInNode == checkInNode,
            "Invalid checkIn node signature"
        );

        checkedIn[userAddr][today] = true;
        nonces[userAddr]++;
        powerAsset.mintCheckInRewards(userAddr, checkInNode, msg.sender);

        emit CheckedIn(userAddr, checkInNode, msg.sender, today);
    }

    function hasCheckedInToday(address userAddr) external view returns (bool) {
        return checkedIn[userAddr][_getToday()];
    }

    function getNonce(address userAddr) external view returns (uint256) {
        return nonces[userAddr];
    }

    function getVerifierNodeForToday(
        address userAddr
    ) external view returns (address) {
        return verifierNodeForDay[userAddr][_getToday()];
    }

    function _checkIsNode(address addr) internal view {
        require(nodeManager.isNode(addr), "Invalid Node");
    }

    function _getToday() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }
}

contracts/V1.0.3/NodeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract NodeManagerV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    address[] public nodeList;
    mapping(address => bool) public isNode;

    event NodeAdded(address node);
    event NodeRemoved(address node);

    modifier onlyNode() {
        require(isNode[msg.sender], "Caller is not a valid node");
        _;
    }

    function initialize() public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function getNodeList() external view returns (address[] memory) {
        return nodeList;
    }

    function addNode(address node) external onlyOwner whenNotPaused {
        require(!isNode[node], "Node already exists");
        require(node != address(0), "Invalid node address");
        isNode[node] = true;
        nodeList.push(node);
        emit NodeAdded(node);
    }

    function removeNode(address node) external onlyOwner whenNotPaused {
        require(isNode[node], "Node not found");
        for (uint256 i = 0; i < nodeList.length; i++) {
            if (nodeList[i] == node) {
                nodeList[i] = nodeList[nodeList.length - 1];
                nodeList.pop();
                break;
            }
        }
        isNode[node] = false;
        emit NodeRemoved(node);
    }
}

contracts/V1.0.3/PowerAsset.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";

interface IAccountRegistrar {
    function referral(address userAddr) external view returns (address);
}

contract PowerAssetV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable,
    ERC20Upgradeable
{
    using ECDSA for bytes32;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _TRANSFER_TYPEHASH =
        keccak256(
            "Transfer(address from,address to,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public startTime;
    address public accountRegistrar;
    address public checkInManager;
    address public stakeController;

    mapping(address => uint256) public nonces;
    mapping(address => bool) public authorizedContracts;

    event Mint(address indexed to, uint256 amount);

    function initialize(
        string memory name_,
        string memory symbol_
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __EIP712_init("Aiverse-Power-Asset", "1");
        __Pausable_init();
        __ReentrancyGuard_init();
        __ERC20_init(name_, symbol_);
        startTime = block.timestamp;
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function setAccountRegistrar(
        address _accountRegistrar
    ) external onlyOwner whenNotPaused {
        require(_accountRegistrar != address(0), "Invalid address");
        accountRegistrar = _accountRegistrar;
    }

    function setCheckInManager(
        address _checkInManager
    ) external onlyOwner whenNotPaused {
        require(_checkInManager != address(0), "Invalid address");
        checkInManager = _checkInManager;
    }

    function setStakeController(
        address _stakeController
    ) external onlyOwner whenNotPaused {
        require(_stakeController != address(0), "Invalid address");
        stakeController = _stakeController;
    }

    function setAuthorizedContract(
        address contractAddr,
        bool authorized
    ) external onlyOwner whenNotPaused {
        require(contractAddr != address(0), "Invalid contract address");
        authorizedContracts[contractAddr] = authorized;
    }

    function transfer(
        address to,
        uint256 amount
    ) public override nonReentrant whenNotPaused returns (bool) {
        return super.transfer(to, amount);
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) public override nonReentrant whenNotPaused returns (bool) {
        require(
            msg.sender == stakeController || authorizedContracts[msg.sender],
            "Only StakeController or authorized contracts can transfer"
        );
        _transfer(from, to, amount);
        return true;
    }

    function transferWithSig(
        address from,
        address to,
        uint256 amount,
        uint256 expireAt,
        bytes memory fromSignature
    ) external nonReentrant whenNotPaused {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        bytes32 structHash = keccak256(
            abi.encode(
                _TRANSFER_TYPEHASH,
                from,
                to,
                amount,
                nonces[from],
                block.chainid,
                expireAt,
                msg.sender
            )
        );

        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(fromSignature);
        require(recovered == from, "Invalid signature");
        nonces[from]++;

        _transfer(from, to, amount);
    }

    function mintRegistrationRewards(
        address userAddr,
        address foundationNode
    ) external nonReentrant whenNotPaused {
        require(
            msg.sender == accountRegistrar,
            "Only AccountRegistrar can mint"
        );
        require(
            userAddr != address(0) && foundationNode != address(0),
            "Invalid address"
        );

        uint256 divisor = _getCurrentDivisor();

        uint256 userReward = (100 * 10 ** decimals()) / divisor;
        uint256 foundationNodeReward = (25 * 10 ** decimals()) / divisor;

        _mint(userAddr, userReward);
        _mint(foundationNode, foundationNodeReward);

        emit Mint(userAddr, userReward);
        emit Mint(foundationNode, foundationNodeReward);
    }

    function mintCheckInRewards(
        address userAddr,
        address checkInNode,
        address verifierNode
    ) external nonReentrant whenNotPaused {
        require(msg.sender == checkInManager, "Only CheckInManager can mint");
        require(
            userAddr != address(0) &&
                checkInNode != address(0) &&
                verifierNode != address(0),
            "Invalid address"
        );
        address referer = IAccountRegistrar(accountRegistrar).referral(
            userAddr
        );

        uint256 divisor = _getCurrentDivisor();

        uint256 userReward = (20 * 10 ** decimals()) / divisor;
        uint256 checkInNodeReward = (3 * 10 ** decimals()) / divisor;
        uint256 verifierReward = (2 * 10 ** decimals()) / divisor;
        uint256 refererReward = (5 * 10 ** decimals()) / divisor;

        _mint(userAddr, userReward);
        _mint(checkInNode, checkInNodeReward);
        _mint(verifierNode, verifierReward);
        _mint(referer, refererReward);

        emit Mint(userAddr, userReward);
        emit Mint(checkInNode, checkInNodeReward);
        emit Mint(verifierNode, verifierReward);
        emit Mint(referer, refererReward);
    }

    function _getCurrentDivisor() internal view returns (uint256) {
        uint256 yearsSinceStart = (block.timestamp - startTime) / (365 days);
        uint256 divisor = 2 ** Math.min(yearsSinceStart / 4, 255);
        require(divisor > 0, "Divisor cannot be zero");
        return divisor;
    }
}

contracts/V1.0.3/StakeController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

interface IPowerAsset {
    function transfer(address to, uint256 amount) external;

    function transferFrom(address from, address to, uint256 amount) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function getNodeList() external view returns (address[] memory);
}

interface IAiverseCoin {
    function getMintAmountByDay(uint256 day) external view returns (uint256);

    function mintToken() external;

    function userClaimToken(address userAddr, uint256 amount) external;
}

contract StakeControllerV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    struct StakeInfo {
        uint256 power;
        uint256 lastSettledDay;
        uint256 unclaimedReward;
    }

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _STAKE_TYPEHASH =
        keccak256(
            "Stake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _UNSTAKE_TYPEHASH =
        keccak256(
            "Unstake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _CLAIM_TYPEHASH =
        keccak256(
            "Claim(address userAddr,address node,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public constant MINE_REWARD_PERCENTAGE = 90;
    uint256 constant NODE_REWARD_COEF = 20;
    uint256 constant USER_REWARD_COEF = 80;
    uint256 public constant MAX_DAYS_FOR_REWARD = 7;

    mapping(address => uint256) public nonces;
    mapping(uint256 => uint256) public rewardPerPower;
    mapping(address => uint256) public nodeTotalPower;
    mapping(address => uint256) public nodeLastSettledDay;
    mapping(uint256 => uint256) public totalPowerSnapshot;
    mapping(uint256 => mapping(address => uint256))
        public nodeTotalPowerSnapshot;
    mapping(address => mapping(address => StakeInfo)) public userStakeInfo;
    mapping(address => address[]) public userStakedNodes;

    uint256 public currentSnapshotDay;
    uint256 public totalPower;
    address public aicoinAddr;
    address public powerAssetAddr;
    address public nodeManagerAddr;

    event Staked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event Unstaked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event UserClaimReward(
        address indexed userAddr,
        address indexed node,
        uint256 reward
    );
    event NodeClaimReward(address indexed node, uint256 reward);

    function initialize(
        address _aicoinAddr,
        address _powerAssetAddr,
        address _nodeManagerAddr
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-Stake-Controller", "1");
        __ReentrancyGuard_init();

        aicoinAddr = _aicoinAddr;
        powerAssetAddr = _powerAssetAddr;
        nodeManagerAddr = _nodeManagerAddr;
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function stake(address node, uint256 amount) external nonReentrant {
        _stake(msg.sender, node, amount);
        IPowerAsset(powerAssetAddr).transfer(address(this), amount);
    }

    function stakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _STAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _stake(userAddr, node, amount);

        IPowerAsset(powerAssetAddr).transferFrom(
            userAddr,
            address(this),
            amount
        );
    }

    function unstake(address node, uint256 amount) external nonReentrant {
        _unstake(msg.sender, node, amount);
        IPowerAsset(powerAssetAddr).transfer(msg.sender, amount);
    }

    function unstakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _UNSTAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _unstake(userAddr, node, amount);

        IPowerAsset(powerAssetAddr).transferFrom(
            address(this),
            userAddr,
            amount
        );
    }

    function nodeClaimReward() external nonReentrant {
        _checkIsNode(msg.sender);
        _nodeClaimReward(msg.sender);
    }

    function userClaimReward(address node) external nonReentrant {
        _userClaimReward(msg.sender, node);
    }

    function userClaimRewardWithSig(
        address userAddr,
        address node,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _CLAIM_TYPEHASH,
                userAddr,
                node,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _userClaimReward(userAddr, node);
    }

    function dailySettle() external onlyOwner nonReentrant {
        require(totalPower > 0, "No power staked");
        uint256 currentDay = _getCurrentDay();
        require(currentDay > currentSnapshotDay, "Already Snapshot today");
        IAiverseCoin(aicoinAddr).mintToken();
        totalPowerSnapshot[currentDay] = totalPower;
        uint256 totalReward = IAiverseCoin(aicoinAddr).getMintAmountByDay(
            currentDay
        );
        uint256 mineReward = (totalReward * MINE_REWARD_PERCENTAGE) / 100;
        uint256 foundationReward = totalReward - mineReward;
        _transferToken(INodeManager(nodeManagerAddr).owner(), foundationReward);

        address[] memory allNodes = INodeManager(nodeManagerAddr).getNodeList();
        for (uint i = 0; i < allNodes.length; i++) {
            address node = allNodes[i];
            nodeTotalPowerSnapshot[currentDay][node] = nodeTotalPower[node];
        }

        uint256 unitReward = (mineReward * 1e18) / totalPower;
        rewardPerPower[currentDay] = unitReward;

        currentSnapshotDay = currentDay;
    }

    function _stake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");

        bool isNewStake = true;
        for (uint i = 0; i < userStakedNodes[userAddr].length; i++) {
            if (userStakedNodes[userAddr][i] == node) {
                isNewStake = false;
                break;
            }
        }
        if (isNewStake) {
            userStakedNodes[userAddr].push(node);
        }

        uint256 currentDay = _getCurrentDay();
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power += amount;
        nodeTotalPower[node] += amount;
        totalPower += amount;

        emit Staked(userAddr, node, amount);
    }

    function _unstake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");
        require(
            userStakeInfo[userAddr][node].power >= amount,
            "Insufficient staked amount"
        );

        uint256 currentDay = _getCurrentDay();
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power -= amount;
        nodeTotalPower[node] -= amount;
        totalPower -= amount;

        emit Unstaked(userAddr, node, amount);
    }

    function _nodeClaimReward(address node) internal {
        uint256 currentDay = _getCurrentDay();
        uint256 lastSettledDay = nodeLastSettledDay[node];

        uint256 reward = 0;
        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = (currentDay - MAX_DAYS_FOR_REWARD >
                lastSettledDay)
                ? currentDay - MAX_DAYS_FOR_REWARD
                : lastSettledDay;
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                uint256 powerSnapShot = nodeTotalPowerSnapshot[day][node];
                reward +=
                    ((rewardPerUnit * powerSnapShot) * NODE_REWARD_COEF) /
                    100 /
                    1e18;
            }
        }

        require(reward > 0, "No rewards available");

        nodeLastSettledDay[node] = currentDay;

        _transferToken(node, reward);
        emit NodeClaimReward(node, reward);
    }

    function _userClaimReward(address userAddr, address node) internal {
        StakeInfo storage info = userStakeInfo[userAddr][node];

        if (info.power > 0) {
            uint256 currentDay = _getCurrentDay();
            _settleUserPendingRewards(userAddr, node, currentDay);
        }

        uint256 reward = info.unclaimedReward;
        require(reward > 0, "No rewards available");

        info.unclaimedReward = 0;

        _transferToken(userAddr, reward);
        emit UserClaimReward(userAddr, node, reward);
    }

    function _transferToken(address to, uint256 amount) internal {
        IAiverseCoin(aicoinAddr).userClaimToken(to, amount);
    }

    function _settleUserPendingRewards(
        address userAddr,
        address node,
        uint256 currentDay
    ) internal {
        StakeInfo storage stakeInfo = userStakeInfo[userAddr][node];
        uint256 lastSettledDay = stakeInfo.lastSettledDay;
        uint256 reward = _calculateReward(
            stakeInfo.power,
            lastSettledDay,
            currentDay
        );
        if (reward > 0) {
            stakeInfo.unclaimedReward += reward;
            stakeInfo.lastSettledDay = currentDay;
        }
    }

    function _calculateReward(
        uint256 power,
        uint256 lastSettledDay,
        uint256 currentDay
    ) internal view returns (uint256) {
        uint256 totalReward = 0;

        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = (currentDay - MAX_DAYS_FOR_REWARD >
                lastSettledDay)
                ? currentDay - MAX_DAYS_FOR_REWARD
                : lastSettledDay;
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                totalReward +=
                    ((rewardPerUnit * power) * USER_REWARD_COEF) /
                    100 /
                    1e18;
            }
        }
        return totalReward;
    }

    function _getCurrentDay() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    function _checkIsNode(address addr) internal view {
        require(INodeManager(nodeManagerAddr).isNode(addr), "Invalid Caller");
    }

    function _checkSigExpire(uint256 expireAt) internal view {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );
    }
}

