// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IPowerAsset {
    function mintRegistrationRewards(
        address userAddr,
        address registrationNode
    ) external;
}

contract AccountRegistrar is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;

    bytes32 private constant _REGISTRATION_TYPEHASH =
        keccak256(
            "Registration(address userAddr,bytes32 emailHash,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    IPowerAsset public powerAsset;

    mapping(address => bytes32) public userEmailHash;
    mapping(bytes32 => address) public emailHashToAddr;
    mapping(address => uint256) public nonces;

    event UserRegistered(address indexed user, bytes32 emailHash);

    function initialize(address _powerAssetAddr) public virtual initializer {
        __Ownable_init(msg.sender);
        __EIP712_init("Aiverse-Account-Registrar", "1");
        __Pausable_init();
        __ReentrancyGuard_init();

        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function registerByEmail(
        address userAddr,
        bytes32 emailHash,
        bytes memory ownerSignature,
        bytes memory userSignature,
        uint256 expireAt
    ) external onlyOwner nonReentrant {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );
        require(userAddr != address(0), "Invalid user address");

        require(
            emailHashToAddr[emailHash] == address(0),
            "Email already registered"
        );
        require(
            userEmailHash[userAddr] == bytes32(0),
            "Address already registered"
        );

        _verifySignature(
            userAddr,
            emailHash,
            ownerSignature,
            owner(),
            expireAt
        );
        _verifySignature(
            userAddr,
            emailHash,
            userSignature,
            userAddr,
            expireAt
        );

        _register(userAddr, emailHash);
    }

    function _verifySignature(
        address userAddr,
        bytes32 emailHash,
        bytes memory signature,
        address expectedSigner,
        uint256 expireAt
    ) internal view {
        bytes32 structHash = keccak256(
            abi.encode(
                _REGISTRATION_TYPEHASH,
                userAddr,
                emailHash,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(signature);
        require(recovered == expectedSigner, "Invalid signature");
    }

    function _register(address userAddr, bytes32 emailHash) internal {
        nonces[userAddr]++;
        userEmailHash[userAddr] = emailHash;
        emailHashToAddr[emailHash] = userAddr;
        powerAsset.mintRegistrationRewards(userAddr, msg.sender);
        emit UserRegistered(userAddr, emailHash);
    }
}

contracts/V1/AiverseCoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract AiverseCoin is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable
{
    uint256 public constant HALVING_PERIOD_DAYS = 1460;
    uint256 public constant MAX_TOTAL_SUPPLY = 210_000_000_000 ether;

    uint256 public initialDailyReward;
    uint256 public startDay;
    address public stakeController;
    uint256 public lastMintedDay;

    function initialize(
        string memory name_,
        string memory symbol_
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ERC20_init(name_, symbol_);
        __ReentrancyGuard_init();
        startDay = block.timestamp / 1 days;
        initialDailyReward = (MAX_TOTAL_SUPPLY / 2) / HALVING_PERIOD_DAYS;
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function setStakeController(address _stakeController) external onlyOwner {
        stakeController = _stakeController;
    }

    function mintToken() external onlyOwner {
        uint256 currentDay = block.timestamp / 1 days;
        require(currentDay > lastMintedDay, "Already minted for today");

        uint256 amount = getMintAmountByDay(currentDay);
        require(
            totalSupply() + amount <= MAX_TOTAL_SUPPLY,
            "Exceeds max supply"
        );

        lastMintedDay = currentDay;
        _mint(address(this), amount);
    }

    function userClaimToken(address userAddr, uint256 amount) external {
        require(
            msg.sender == stakeController,
            "Only StakeController can transfer"
        );
        _transfer(address(this), userAddr, amount);
    }

    function getMintAmountByDay(uint256 day) public view returns (uint256) {
        require(day >= startDay, "Invalid day");

        uint256 daysSinceStart = day - startDay;
        uint256 halvingEra = daysSinceStart / HALVING_PERIOD_DAYS;

        uint256 reward = initialDailyReward >> halvingEra;
        return reward;
    }
}

contracts/V1/AiverseFund.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract AiverseFund is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;

    IERC20 public aicoin;
    IERC20 public usdt;

    uint256 public minPurchaseAmount;
    uint256 public price;

    uint256 public totalSold;
    uint256 public totalUSDTReceived;

    event TokensPurchased(
        address indexed buyer,
        uint256 aicoinAmount,
        uint256 usdtAmount,
        uint256 timestamp
    );
    event PriceUpdated(uint256 oldPrice, uint256 newPrice);
    event USDTWithdrawn(address indexed to, uint256 amount);
    event AICOINWithdrawn(address indexed to, uint256 amount);
    event AICOINDeposited(address indexed from, uint256 amount);

    function initialize(
        address _aicoinAddr,
        address _usdtAddr,
        uint256 _minPurchaseAmount,
        uint256 _price
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();

        require(_aicoinAddr != address(0), "Invalid AICOIN address");
        require(_usdtAddr != address(0), "Invalid USDT address");
        require(
            _minPurchaseAmount > 0,
            "Min purchase amount must be greater than 0"
        );
        require(_price > 0, "Price must be greater than 0");

        aicoin = IERC20(_aicoinAddr);
        usdt = IERC20(_usdtAddr);
        minPurchaseAmount = _minPurchaseAmount;
        price = _price;
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setMinPurchaseAmount(
        uint256 _minPurchaseAmount
    ) external onlyOwner {
        require(
            _minPurchaseAmount > 0,
            "Min purchase amount must be greater than 0"
        );
        minPurchaseAmount = _minPurchaseAmount;
    }

    function setPrice(uint256 _price) external onlyOwner {
        require(_price > 0, "Price must be greater than 0");
        uint256 oldPrice = price;
        price = _price;
        emit PriceUpdated(oldPrice, _price);
    }

    function depositAICOIN(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be greater than 0");

        uint256 allowance = aicoin.allowance(msg.sender, address(this));
        require(allowance >= amount, "Insufficient AICOIN allowance");

        aicoin.safeTransferFrom(msg.sender, address(this), amount);

        emit AICOINDeposited(msg.sender, amount);
    }

    function purchaseWithUSDT(
        uint256 usdtAmount
    ) external nonReentrant whenNotPaused {
        (
            bool canPurchase,
            string memory reason,
            uint256 aicoinAmount
        ) = canUserPurchase(msg.sender, usdtAmount);
        require(canPurchase, reason);

        totalSold += aicoinAmount;
        totalUSDTReceived += usdtAmount;

        usdt.safeTransferFrom(msg.sender, address(this), usdtAmount);
        aicoin.safeTransfer(msg.sender, aicoinAmount);

        emit TokensPurchased(
            msg.sender,
            aicoinAmount,
            usdtAmount,
            block.timestamp
        );
    }

    function withdrawUSDT() external onlyOwner nonReentrant {
        uint256 balance = usdt.balanceOf(address(this));
        require(balance > 0, "No USDT to withdraw");
        usdt.safeTransfer(msg.sender, balance);
        emit USDTWithdrawn(msg.sender, balance);
    }

    function withdrawAICOIN() external onlyOwner nonReentrant {
        uint256 balance = aicoin.balanceOf(address(this));
        require(balance > 0, "No AICOIN to withdraw");
        aicoin.safeTransfer(msg.sender, balance);
        emit AICOINWithdrawn(msg.sender, balance);
    }

    function emergencyWithdrawToken(
        address tokenAddress
    ) external onlyOwner nonReentrant {
        require(tokenAddress != address(0), "Invalid token address");
        IERC20 token = IERC20(tokenAddress);
        uint256 balance = token.balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");
        token.safeTransfer(msg.sender, balance);
    }

    function getAICOINBalance() public view returns (uint256) {
        return aicoin.balanceOf(address(this));
    }

    function getUSDTBalance() public view returns (uint256) {
        return usdt.balanceOf(address(this));
    }

    function getUserUSDTAllowance(address user) public view returns (uint256) {
        return usdt.allowance(user, address(this));
    }

    function getUserUSDTBalance(address user) public view returns (uint256) {
        return usdt.balanceOf(user);
    }

    function calculateAICOINAmount(
        uint256 usdtAmount
    ) public view returns (uint256) {
        return (usdtAmount * 1e18) / price;
    }

    function calculateUSDTAmount(
        uint256 aicoinAmount
    ) public view returns (uint256) {
        return (aicoinAmount * price) / 1e18;
    }

    function getMaxAcceptableUSDT() public view returns (uint256) {
        return calculateUSDTAmount(getAICOINBalance());
    }

    function canUserPurchase(
        address user,
        uint256 usdtAmount
    )
        public
        view
        returns (bool canPurchase, string memory reason, uint256 aicoinAmount)
    {
        aicoinAmount = calculateAICOINAmount(usdtAmount);

        if (aicoinAmount < minPurchaseAmount) {
            return (false, "Below minimum purchase amount", 0);
        }

        if (getAICOINBalance() < aicoinAmount) {
            return (false, "Insufficient AICOIN in contract", 0);
        }

        if (getUserUSDTAllowance(user) < usdtAmount) {
            return (false, "Insufficient USDT allowance", 0);
        }

        if (getUserUSDTBalance(user) < usdtAmount) {
            return (false, "Insufficient USDT balance", 0);
        }

        return (true, "", aicoinAmount);
    }

    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    fallback() external payable {
        revert("Fallback not allowed");
    }
}

contracts/V1/AiverseTopUp.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

/// @title AiverseTopUp — Agent credit USDC top-up (platform relay + EIP-2612)
/// @notice UUPS upgradeable implementation: logic contract sits behind an `ERC1967Proxy`; upgrades are performed by `owner` via `upgradeToAndCall`.
///         Ownership uses two-step transfer (`Ownable2StepUpgradeable`): `transferOwnership` only sets a pending owner; the new owner must call `acceptOwnership` to complete the handover.
///         USDC is stored as `IERC20` and set at deploy/init; amounts are raw `uint256` (USDC commonly uses 6 decimals).
///         Permit EIP-712 must align with the proxy address, `DOMAIN_SEPARATOR`, and `nonces(owner)`.
/// @dev **Call model:** only `platform` allowlisted addresses may call `depositWithPermit`; user EOAs do not call this contract directly,
///      they only sign `permit(owner, address(this), amount, deadline, v, r, s)` off-chain (`address(this)` is the proxy).
///      Per-transaction flow: after checks, set `usedPaymentId[paymentId] = true` (CEI), then optionally call `permit` depending on `allowance` (`try`/`catch` tolerates a frontrunner that already consumed the signature), then `safeTransferFrom`;
///      if allowance is still insufficient, `safeTransferFrom` reverts, the whole transaction rolls back, and the mapping is not left incorrectly set to true.
/// @dev **`paymentId` binding:** the supplied `paymentId` must equal
///      `keccak256(abi.encode(block.chainid, address(this), address(usdc), owner, amount, deadline, productType))`;
///      it includes `address(usdc)` so after `setUsdc` the same tuple yields a new id, avoiding stale `usedPaymentId` entries affecting deposits with a new token.
///      `productType` is an application-defined discriminator (e.g. SKU / product line) and must match off-chain billing.
///      Off-chain `PlatformOnchainPayment.id` must be precomputed with the same encoding (including `productType`) and match the token address used in Permit (`address(this)` is the proxy).
/// @dev **On-chain idempotency (scheme B):** `paymentId` is globally unique and must not be reused; set `usedPaymentId[paymentId] = true` **before** external `permit` / `transferFrom` (CEI / limits reentrancy windows if the implementation is extended later). If later external calls fail, the entire transaction reverts and this write rolls back. Duplicate `paymentId` reverts `PaymentIdAlreadyUsed()`. `permit` may be frontrun; when allowance is insufficient a valid signature/nonce is still required or `safeTransferFrom` fails.
///
/// **Explicit revert reasons in this contract:**
/// - `NotPlatform()` — `msg.sender` is not on the platform allowlist
/// - `ZeroAddress()` — zero address argument
/// - `ZeroTreasury()` — `treasury` is not configured
/// - `InvalidAmount()` — `amount == 0`
/// - `BelowMinDeposit()` / `AboveMaxDeposit()` — amount bounds
/// - `PaymentIdMismatch()` — `paymentId` does not match `owner` / `amount` / `deadline` / `productType` / `address(usdc)` (plus chain id and this contract address)
/// - `PaymentIdAlreadyUsed()` — `paymentId` already consumed (marked before this external path or from a prior successful settlement)
/// - `PermitExpired()` — `deadline` has passed
/// - `EnforcedPause()` / `ReentrancyGuardReentrantCall()` — OpenZeppelin modules
/// - `StuckUsdcInContract()` — this contract still holds a balance of the previous `usdc` when `setUsdc` is called
/// - UUPS: `UUPSUnauthorizedCallContext` / `UUPSUnsupportedProxiableUUID`, etc. (see OpenZeppelin documentation)

contract AiverseTopUp is
    Initializable,
    Ownable2StepUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    IERC20 public usdc;

    address public treasury;

    uint256 public minDeposit;
    uint256 public maxDeposit;

    mapping(address => bool) public isPlatform;

    /// @notice `paymentId` logically reserved (set before external calls; reverts in the same tx roll this back)
    mapping(bytes32 => bool) public usedPaymentId;

    event UsdcDepositSettled(
        bytes32 indexed paymentId,
        address indexed owner,
        address indexed treasury,
        address token,
        uint256 amount,
        uint256 deadline,
        uint256 productType
    );

    event TreasuryUpdated(
        address indexed previousTreasury,
        address indexed newTreasury
    );
    event PlatformCallerUpdated(address indexed account, bool allowed);
    event MinDepositUpdated(uint256 previousMin, uint256 newMin);
    event MaxDepositUpdated(uint256 previousMax, uint256 newMax);
    event UsdcUpdated(address indexed previousUsdc, address indexed newUsdc);

    error NotPlatform();
    error ZeroAddress();
    error ZeroTreasury();
    error InvalidAmount();
    error BelowMinDeposit();
    error AboveMaxDeposit();
    error PermitExpired();
    error PaymentIdMismatch();
    error PaymentIdAlreadyUsed();
    error StuckUsdcInContract();

    modifier onlyPlatform() {
        if (!isPlatform[msg.sender]) revert NotPlatform();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @param initialOwner Owner set when initializing the proxy after deployment; may be a multisig or Timelock
    /// @param usdc_ USDC token contract address
    /// @param treasury_ Platform payout recipient
    /// @param initialPlatform First address allowed to call `depositWithPermit`
    function initialize(
        address initialOwner,
        address usdc_,
        address treasury_,
        address initialPlatform
    ) public initializer {
        if (initialOwner == address(0)) revert ZeroAddress();
        if (usdc_ == address(0)) revert ZeroAddress();
        if (treasury_ == address(0)) revert ZeroAddress();
        if (initialPlatform == address(0)) revert ZeroAddress();

        __Ownable_init(initialOwner);
        __Ownable2Step_init();
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        usdc = IERC20(usdc_);
        treasury = treasury_;
        isPlatform[initialPlatform] = true;

        emit TreasuryUpdated(address(0), treasury_);
        emit PlatformCallerUpdated(initialPlatform, true);
        emit UsdcUpdated(address(0), usdc_);
    }

    function version() external pure returns (string memory) {
        return "1.0.0";
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice Replace the USDC address (e.g. wrong testnet vs mainnet configuration); requires this contract's balance of the current `usdc` to be zero to avoid stranded funds.
    ///         `computePaymentId` includes `address(usdc)`; off-chain systems must recompute `paymentId` using the new token address after a switch.
    function setUsdc(address newUsdc) external onlyOwner {
        if (newUsdc == address(0)) revert ZeroAddress();
        address previous = address(usdc);
        if (
            previous != address(0) &&
            IERC20(previous).balanceOf(address(this)) != 0
        ) {
            revert StuckUsdcInContract();
        }
        usdc = IERC20(newUsdc);
        emit UsdcUpdated(previous, newUsdc);
    }

    /// @notice Recover ERC20 tokens mistakenly sent to this contract; clears balances so `setUsdc` and similar operations can proceed
    /// @param token Token contract address (may be the current `usdc` to clear `StuckUsdcInContract` when `setUsdc` would otherwise be blocked)
    function rescueERC20(
        address token,
        address to,
        uint256 amount
    ) external onlyOwner nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        IERC20(token).safeTransfer(to, amount);
    }

    function setTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert ZeroAddress();
        address previous = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(previous, newTreasury);
    }

    function setPlatform(address account, bool allowed) external onlyOwner {
        if (account == address(0)) revert ZeroAddress();
        isPlatform[account] = allowed;
        emit PlatformCallerUpdated(account, allowed);
    }

    function setMinDeposit(uint256 newMinDeposit) external onlyOwner {
        uint256 previous = minDeposit;
        minDeposit = newMinDeposit;
        emit MinDepositUpdated(previous, newMinDeposit);
    }

    function setMaxDeposit(uint256 newMaxDeposit) external onlyOwner {
        uint256 previous = maxDeposit;
        maxDeposit = newMaxDeposit;
        emit MaxDepositUpdated(previous, newMaxDeposit);
    }

    /// @notice Computes `paymentId` the same way as `depositWithPermit` for off-chain preparation and reconciliation
    /// @dev `keccak256(abi.encode(block.chainid, address(this), address(usdc), owner, amount, deadline, productType))`
    /// @param productType Application-defined product discriminator bound into `paymentId`
    function computePaymentId(
        address owner,
        uint256 amount,
        uint256 deadline,
        uint256 productType
    ) public view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    block.chainid,
                    address(this),
                    address(usdc),
                    owner,
                    amount,
                    deadline,
                    productType
                )
            );
    }

    /// @notice Platform-relayed deposit: optionally raises allowance via `permit` (`try`/`catch` tolerates frontrunners who already submitted `permit`), then `transferFrom` to `treasury`
    /// @param productType Application-defined product discriminator; must be included in off-chain `paymentId` and here identically
    function depositWithPermit(
        bytes32 paymentId,
        address owner,
        uint256 amount,
        uint256 deadline,
        uint256 productType,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external onlyPlatform whenNotPaused nonReentrant {
        if (owner == address(0)) revert ZeroAddress();
        if (treasury == address(0)) revert ZeroTreasury();
        if (amount == 0) revert InvalidAmount();
        if (amount < minDeposit) revert BelowMinDeposit();
        if (maxDeposit != 0 && amount > maxDeposit) revert AboveMaxDeposit();
        if (deadline < block.timestamp) revert PermitExpired();

        if (paymentId != computePaymentId(owner, amount, deadline, productType))
            revert PaymentIdMismatch();
        if (usedPaymentId[paymentId]) revert PaymentIdAlreadyUsed();

        usedPaymentId[paymentId] = true;

        IERC20 usdc_ = usdc;
        if (usdc_.allowance(owner, address(this)) < amount) {
            try
                IERC20Permit(address(usdc_)).permit(
                    owner,
                    address(this),
                    amount,
                    deadline,
                    v,
                    r,
                    s
                )
            {} catch {}
        }
        usdc_.safeTransferFrom(owner, treasury, amount);

        emit UsdcDepositSettled(
            paymentId,
            owner,
            treasury,
            address(usdc_),
            amount,
            deadline,
            productType
        );
    }

    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyOwner {}

    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    fallback() external payable {
        revert("Fallback not allowed");
    }
}

contracts/V1/AiverseTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

interface IAiverseCoinTransferWithSig {
    function transferWithSig(
        address from,
        address to,
        uint256 amount,
        uint256 deadline,
        bytes memory fromSignature
    ) external;
}

/// @title AiverseTreasury — AICOIN custody: deposit via token `transferWithSig`, claim via dual EIP-712
/// @notice UUPS proxy; `owner` upgrades. Deposits pull AICOIN into this contract using the user's AICOIN EIP-712 signature
///         (`executor` in that signature must be `address(this)`, the Treasury proxy). Claims pay out from this balance
///         after user + `signer` both sign the Treasury EIP-712 claim digest. Only `signer` may call `deposit` / `claim`.
/// @dev `operationId` is namespaced by a `kind` byte to keep deposit and claim ID spaces disjoint:
///      `keccak256(abi.encode(kind, chainid, this, aicoin, account, amount, deadline))`
///      where `kind = OP_KIND_DEPOSIT (0x01)` for `deposit` and `OP_KIND_CLAIM (0x02)` for `claim`.
///      `aicoin` is set once at `initialize` and is not mutable thereafter.
///      AICOIN must whitelist this proxy (`setWhitelistAddr`) so `transferWithSig` succeeds when called from here.
contract AiverseTreasury is
    Initializable,
    Ownable2StepUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    EIP712Upgradeable,
    UUPSUpgradeable
{
    using ECDSA for bytes32;
    using SafeERC20 for IERC20;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;

    /// @notice `operationId` kind discriminator for `deposit` flows
    bytes1 public constant OP_KIND_DEPOSIT = 0x01;
    /// @notice `operationId` kind discriminator for `claim` flows
    bytes1 public constant OP_KIND_CLAIM = 0x02;

    bytes32 private constant _CLAIM_TYPEHASH =
        keccak256(
            "Claim(address token,address recipient,uint256 amount,bytes32 operationId,uint256 nonce,uint256 chainid,uint256 deadline)"
        );

    IERC20 public aicoin;
    address public signer;

    uint256 public minDeposit;
    uint256 public maxDeposit;

    uint256 public minClaim;
    uint256 public maxClaim;

    mapping(bytes32 => bool) public usedOperationId;
    mapping(address => uint256) public claimNonces;

    event AicoinDeposited(
        bytes32 indexed operationId,
        address indexed payer,
        uint256 amount,
        uint256 deadline
    );
    event AicoinClaimed(
        bytes32 indexed operationId,
        address indexed recipient,
        uint256 amount,
        uint256 deadline
    );
    event SignerUpdated(
        address indexed previousSigner,
        address indexed newSigner
    );
    event AicoinUpdated(
        address indexed previousAicoin,
        address indexed newAicoin
    );
    event MinDepositUpdated(uint256 previousMin, uint256 newMin);
    event MaxDepositUpdated(uint256 previousMax, uint256 newMax);
    event MinClaimUpdated(uint256 previousMin, uint256 newMin);
    event MaxClaimUpdated(uint256 previousMax, uint256 newMax);

    error NotSigner();
    error ZeroAddress();
    error InvalidAmount();
    error BelowMinDeposit();
    error AboveMaxDeposit();
    error BelowMinClaim();
    error AboveMaxClaim();
    error DeadlineExpired();
    error DeadlineTooFar();
    error OperationIdMismatch();
    error OperationIdAlreadyUsed();
    error InvalidUserSignature();
    error InvalidSignerSignature();
    error InsufficientAicoinBalance();
    error CannotRescueAicoin();

    modifier onlySigner() {
        if (msg.sender != signer) revert NotSigner();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @param initialOwner Upgrade admin (multisig / timelock)
    /// @param aicoin_ AICOIN proxy; must whitelist this Treasury proxy for `transferWithSig`
    /// @dev `signer` is not set here; owner must call `setSigner` before `deposit` / `claim` are usable.
    function initialize(
        address initialOwner,
        address aicoin_
    ) public initializer {
        if (initialOwner == address(0)) revert ZeroAddress();
        if (aicoin_ == address(0)) revert ZeroAddress();

        __Ownable_init(initialOwner);
        __Ownable2Step_init();
        __Pausable_init();
        __ReentrancyGuard_init();
        __EIP712_init("Aiverse-Treasury", "1");
        __UUPSUpgradeable_init();

        aicoin = IERC20(aicoin_);
        emit AicoinUpdated(address(0), aicoin_);
    }

    function version() external pure returns (string memory) {
        return "1.0.0";
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function setSigner(address newSigner) external onlyOwner {
        if (newSigner == address(0)) revert ZeroAddress();
        address previous = signer;
        signer = newSigner;
        emit SignerUpdated(previous, newSigner);
    }

    function setMinDeposit(uint256 newMinDeposit) external onlyOwner {
        uint256 previous = minDeposit;
        minDeposit = newMinDeposit;
        emit MinDepositUpdated(previous, newMinDeposit);
    }

    function setMaxDeposit(uint256 newMaxDeposit) external onlyOwner {
        uint256 previous = maxDeposit;
        maxDeposit = newMaxDeposit;
        emit MaxDepositUpdated(previous, newMaxDeposit);
    }

    function setMinClaim(uint256 newMinClaim) external onlyOwner {
        uint256 previous = minClaim;
        minClaim = newMinClaim;
        emit MinClaimUpdated(previous, newMinClaim);
    }

    function setMaxClaim(uint256 newMaxClaim) external onlyOwner {
        uint256 previous = maxClaim;
        maxClaim = newMaxClaim;
        emit MaxClaimUpdated(previous, newMaxClaim);
    }

    /// @notice Recover ERC20 tokens accidentally sent to this contract.
    /// @dev AICOIN is the custodied asset and is intentionally non-rescuable here
    ///      so that owner cannot bypass the dual-signature `claim` flow.
    function rescueERC20(
        address token,
        address to,
        uint256 amount
    ) external onlyOwner nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        if (token == address(aicoin)) revert CannotRescueAicoin();
        IERC20(token).safeTransfer(to, amount);
    }

    /// @notice Operation id namespaced by `kind` so deposit / claim ID spaces are disjoint.
    /// @param kind `OP_KIND_DEPOSIT` (`account` = payer) or `OP_KIND_CLAIM` (`account` = recipient).
    function computeOperationId(
        bytes1 kind,
        address account,
        uint256 amount,
        uint256 deadline
    ) public view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    kind,
                    block.chainid,
                    address(this),
                    address(aicoin),
                    account,
                    amount,
                    deadline
                )
            );
    }

    /// @notice Pull AICOIN from `payer` into this contract via AICOIN `transferWithSig`
    /// @dev User's AICOIN signature must use `executor = address(this)` (Treasury proxy). Caller must be `signer`.
    function deposit(
        bytes32 operationId,
        address payer,
        uint256 amount,
        uint256 deadline,
        bytes calldata fromSignature
    ) external onlySigner whenNotPaused nonReentrant {
        if (payer == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();
        if (amount < minDeposit) revert BelowMinDeposit();
        if (maxDeposit != 0 && amount > maxDeposit) revert AboveMaxDeposit();
        _validateDeadline(deadline);

        if (
            operationId !=
            computeOperationId(OP_KIND_DEPOSIT, payer, amount, deadline)
        ) revert OperationIdMismatch();
        if (usedOperationId[operationId]) revert OperationIdAlreadyUsed();

        usedOperationId[operationId] = true;

        IAiverseCoinTransferWithSig(address(aicoin)).transferWithSig(
            payer,
            address(this),
            amount,
            deadline,
            fromSignature
        );

        emit AicoinDeposited(operationId, payer, amount, deadline);
    }

    /// @notice Pay AICOIN from this contract to `recipient` after user + signer EIP-712 signatures
    /// @dev Same digest for `userSig` and `signerSig` (CheckIn-style). Caller must be `signer`.
    function claim(
        bytes32 operationId,
        address recipient,
        uint256 amount,
        uint256 deadline,
        bytes calldata userSig,
        bytes calldata signerSig
    ) external onlySigner whenNotPaused nonReentrant {
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();
        if (amount < minClaim) revert BelowMinClaim();
        if (maxClaim != 0 && amount > maxClaim) {
            revert AboveMaxClaim();
        }
        _validateDeadline(deadline);

        if (
            operationId !=
            computeOperationId(OP_KIND_CLAIM, recipient, amount, deadline)
        ) revert OperationIdMismatch();
        if (usedOperationId[operationId]) revert OperationIdAlreadyUsed();

        bytes32 structHash = keccak256(
            abi.encode(
                _CLAIM_TYPEHASH,
                address(aicoin),
                recipient,
                amount,
                operationId,
                claimNonces[recipient],
                block.chainid,
                deadline
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);

        if (digest.recover(userSig) != recipient) {
            revert InvalidUserSignature();
        }
        if (digest.recover(signerSig) != signer) {
            revert InvalidSignerSignature();
        }

        usedOperationId[operationId] = true;
        claimNonces[recipient]++;

        if (aicoin.balanceOf(address(this)) < amount) {
            revert InsufficientAicoinBalance();
        }
        aicoin.safeTransfer(recipient, amount);

        emit AicoinClaimed(operationId, recipient, amount, deadline);
    }

    function _validateDeadline(uint256 deadline) internal view {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (deadline > block.timestamp + SIGNATURE_EXPIRY) {
            revert DeadlineTooFar();
        }
    }

    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyOwner {}

    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    fallback() external payable {
        revert("Fallback not allowed");
    }
}

contracts/V1/BatchTransfer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract BatchTransfer is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;

    IERC20 public aiHash;
    IERC20 public aiCoin;

    mapping(address => bool) public authorizedOperators;
    uint256 public maxBatchSize;

    event OperatorAuthorized(address indexed operator, bool authorized);
    event MaxBatchSizeUpdated(uint256 oldSize, uint256 newSize);
    event BatchTransferAIHASH(
        address indexed sender,
        address[] recipients,
        uint256[] amounts
    );
    event BatchTransferAICOIN(
        address indexed sender,
        address[] recipients,
        uint256[] amounts
    );

    modifier onlyAuthorized() {
        require(
            authorizedOperators[msg.sender] || msg.sender == owner(),
            "Not authorized"
        );
        _;
    }

    function initialize(
        address _aiHashAddr,
        address _aiCoinAddr,
        uint256 _maxBatchSize
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();

        require(_aiHashAddr != address(0), "Invalid AIHASH address");
        require(_aiCoinAddr != address(0), "Invalid AICOIN address");
        require(_maxBatchSize > 0, "Max batch size must be greater than 0");

        aiHash = IERC20(_aiHashAddr);
        aiCoin = IERC20(_aiCoinAddr);
        maxBatchSize = _maxBatchSize;
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setAuthorizedOperator(
        address operator,
        bool authorized
    ) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        authorizedOperators[operator] = authorized;
        emit OperatorAuthorized(operator, authorized);
    }

    function setMaxBatchSize(uint256 _maxBatchSize) external onlyOwner {
        require(_maxBatchSize > 0, "Max batch size must be greater than 0");
        uint256 oldSize = maxBatchSize;
        maxBatchSize = _maxBatchSize;
        emit MaxBatchSizeUpdated(oldSize, _maxBatchSize);
    }

    function batchTransferAIHASH(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external nonReentrant whenNotPaused onlyAuthorized {
        require(
            recipients.length == amounts.length,
            "Recipients and amounts length mismatch"
        );
        require(recipients.length > 0, "Recipients array cannot be empty");
        require(recipients.length <= maxBatchSize, "Exceeds max batch size");

        address sender = msg.sender;

        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient address");
            require(amounts[i] > 0, "Amount must be greater than 0");
            aiHash.safeTransferFrom(sender, recipients[i], amounts[i]);
        }

        emit BatchTransferAIHASH(sender, recipients, amounts);
    }

    function batchTransferAICOIN(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external nonReentrant whenNotPaused onlyAuthorized {
        require(
            recipients.length == amounts.length,
            "Recipients and amounts length mismatch"
        );
        require(recipients.length > 0, "Recipients array cannot be empty");
        require(recipients.length <= maxBatchSize, "Exceeds max batch size");

        address sender = msg.sender;

        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient address");
            require(amounts[i] > 0, "Amount must be greater than 0");
            aiCoin.safeTransferFrom(sender, recipients[i], amounts[i]);
        }

        emit BatchTransferAICOIN(sender, recipients, amounts);
    }

    function getMaxBatchSize() external view returns (uint256) {
        return maxBatchSize;
    }

    function isAuthorized(address operator) external view returns (bool) {
        return authorizedOperators[operator] || operator == owner();
    }

    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    fallback() external payable {
        revert("Fallback not allowed");
    }
}

contracts/V1/CheckInManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IAccountRegistrar {
    function userEmailHash(address user) external view returns (bytes32);
}

interface IPowerAsset {
    function mintCheckInRewards(
        address user,
        address checkInNode,
        address verifierNode
    ) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function nodeList() external view returns (address[] memory);
}

contract CheckInManager is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    INodeManager public nodeManager;
    IAccountRegistrar public accountRegistrar;
    IPowerAsset public powerAsset;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _CHECKIN_TYPEHASH =
        keccak256(
            "CheckIn(address userAddr,address checkInNode,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    mapping(address => uint256) public nonces;
    mapping(address => mapping(uint256 => bool)) public checkedIn;
    mapping(address => mapping(uint256 => address)) public verifierNodeForDay;

    event VerifierNodeSelected(
        address indexed userAddr,
        address indexed verifierNode,
        uint256 indexed day
    );
    event CheckedIn(
        address indexed userAddr,
        address indexed checkInNode,
        address indexed verifierNode,
        uint256 day
    );

    function initialize(
        address _nodeManagerAddr,
        address _registrarAddr,
        address _powerAssetAddr
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-CheckIn-Manager", "1");
        __ReentrancyGuard_init();

        nodeManager = INodeManager(_nodeManagerAddr);
        accountRegistrar = IAccountRegistrar(_registrarAddr);
        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function selectRandomVerifierNode(
        address userAddr
    ) external nonReentrant returns (address) {
        _checkIsNode(msg.sender);
        address[] memory nodeListArray = nodeManager.nodeList();
        require(nodeListArray.length > 1, "Not enough nodes to choose from");

        uint256 today = _getToday();
        require(
            verifierNodeForDay[userAddr][today] == address(0),
            "Verifier node already selected today"
        );

        uint256 randomSeed = uint256(
            keccak256(
                abi.encodePacked(
                    blockhash(block.number - 1),
                    block.prevrandao,
                    block.timestamp,
                    userAddr,
                    nonces[userAddr]
                )
            )
        );

        address verifierNode;
        uint256 attempts = 0;
        uint256 maxAttempts = 5;

        do {
            uint256 randomIndex = randomSeed % nodeListArray.length;
            verifierNode = nodeListArray[randomIndex];
            randomSeed = uint256(keccak256(abi.encodePacked(randomSeed)));
            attempts++;
            require(attempts < maxAttempts, "Failed to select verifier node");
        } while (verifierNode == msg.sender);

        verifierNodeForDay[userAddr][today] = verifierNode;
        emit VerifierNodeSelected(userAddr, verifierNode, today);
        return verifierNode;
    }

    function checkIn(
        address userAddr,
        address checkInNode,
        uint256 expireAt,
        bytes memory userSig,
        bytes memory checkInNodeSig
    ) external nonReentrant {
        _checkIsNode(msg.sender);
        _checkIsNode(checkInNode);
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        uint256 today = _getToday();
        require(
            accountRegistrar.userEmailHash(userAddr) != bytes32(0),
            "User not registered"
        );
        require(!checkedIn[userAddr][today], "Already checked today");

        address verifierNode = verifierNodeForDay[userAddr][today];
        require(verifierNode == msg.sender, "Non-designated verifier node");

        bytes32 structHash = keccak256(
            abi.encode(
                _CHECKIN_TYPEHASH,
                userAddr,
                checkInNode,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);

        address recoveredUser = digest.recover(userSig);
        require(recoveredUser == userAddr, "Invalid user signature");

        address recoveredCheckInNode = digest.recover(checkInNodeSig);
        require(
            recoveredCheckInNode == checkInNode,
            "Invalid checkIn node signature"
        );

        checkedIn[userAddr][today] = true;
        nonces[userAddr]++;
        powerAsset.mintCheckInRewards(userAddr, checkInNode, msg.sender);

        emit CheckedIn(userAddr, checkInNode, msg.sender, today);
    }

    function hasCheckedInToday(address userAddr) external view returns (bool) {
        return checkedIn[userAddr][_getToday()];
    }

    function getNonce(address userAddr) external view returns (uint256) {
        return nonces[userAddr];
    }

    function getVerifierNodeForToday(
        address userAddr
    ) external view returns (address) {
        return verifierNodeForDay[userAddr][_getToday()];
    }

    function _checkIsNode(address addr) internal view {
        require(nodeManager.isNode(addr), "Invalid Node");
    }

    function _getToday() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }
}

contracts/V1/NodeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract NodeManager is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    address[] public nodeList;
    mapping(address => bool) public isNode;

    event NodeAdded(address node);
    event NodeRemoved(address node);

    modifier onlyNode() {
        require(isNode[msg.sender], "Caller is not a valid node");
        _;
    }

    function initialize() public virtual initializer {
        __Ownable_init(msg.sender);
        __ReentrancyGuard_init();
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function addNode(address node) external onlyOwner {
        require(!isNode[node], "Node already exists");
        require(node != address(0), "Invalid node address");
        isNode[node] = true;
        nodeList.push(node);
        emit NodeAdded(node);
    }

    function removeNode(address node) external onlyOwner {
        require(isNode[node], "Node not found");
        isNode[node] = false;

        for (uint256 i = 0; i < nodeList.length; i++) {
            if (nodeList[i] == node) {
                nodeList[i] = nodeList[nodeList.length - 1];
                nodeList.pop();
                break;
            }
        }
        emit NodeRemoved(node);
    }
}

contracts/V1/PowerAsset.sol.content:
// // SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";

contract PowerAsset is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    uint8 public constant DECIMALS = 18;
    uint256 public constant UNIT = 10 ** DECIMALS;
    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _TRANSFER_TYPEHASH =
        keccak256(
            "Transfer(address from,address to,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public startTime;
    uint256 public totalPower;
    address public accountRegistrar;
    address public checkInManager;
    address public stakeController;

    mapping(address => uint256) public nonces;
    mapping(address => uint256) private powerBalance;

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Mint(address indexed to, uint256 amount);

    function initialize() public virtual initializer {
        __Ownable_init(msg.sender);
        __EIP712_init("Aiverse-Power-Asset", "1");
        __Pausable_init();
        __ReentrancyGuard_init();
        startTime = block.timestamp;
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function setAccountRegistrar(address _accountRegistrar) external onlyOwner {
        accountRegistrar = _accountRegistrar;
    }

    function setCheckInManager(address _checkInManager) external onlyOwner {
        checkInManager = _checkInManager;
    }

    function setStakeController(address _stakeController) external onlyOwner {
        stakeController = _stakeController;
    }

    function balanceOf(address userAddr) external view returns (uint256) {
        return powerBalance[userAddr];
    }

    function transfer(address to, uint256 amount) external nonReentrant {
        _transfer(msg.sender, to, amount);
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external nonReentrant {
        require(
            msg.sender == stakeController,
            "Only StakeController can transfer"
        );
        _transfer(from, to, amount);
    }

    function transferWithSig(
        address from,
        address to,
        uint256 amount,
        uint256 expireAt,
        bytes memory fromSignature
    ) external nonReentrant {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        bytes32 structHash = keccak256(
            abi.encode(
                _TRANSFER_TYPEHASH,
                from,
                to,
                amount,
                nonces[from],
                block.chainid,
                expireAt,
                msg.sender
            )
        );

        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(fromSignature);
        require(recovered == from, "Invalid signature");

        nonces[from]++;
        _transfer(from, to, amount);
    }

    function mintRegistrationRewards(
        address userAddr,
        address foundationNode
    ) external nonReentrant {
        require(
            msg.sender == accountRegistrar,
            "Only AccountRegistrar can mint"
        );

        uint256 divisor = 2 ** ((block.timestamp - startTime) / 4 / 365 days);

        uint256 userReward = (100 * UNIT) / divisor;
        uint256 foundationNodeReward = (25 * UNIT) / divisor;

        powerBalance[userAddr] += userReward;
        powerBalance[foundationNode] += foundationNodeReward;

        totalPower += userReward + foundationNodeReward;

        emit Mint(userAddr, userReward);
        emit Mint(foundationNode, foundationNodeReward);
    }

    function mintCheckInRewards(
        address userAddr,
        address checkInNode,
        address verifierNode
    ) external nonReentrant {
        require(msg.sender == checkInManager, "Only CheckInManager can mint");

        uint256 divisor = 2 ** ((block.timestamp - startTime) / 4 / 365 days);

        uint256 userReward = (20 * UNIT) / divisor;
        uint256 checkInNodeReward = (3 * UNIT) / divisor;
        uint256 verifierReward = (2 * UNIT) / divisor;

        powerBalance[userAddr] += userReward;
        powerBalance[checkInNode] += checkInNodeReward;
        powerBalance[verifierNode] += verifierReward;

        totalPower += userReward + checkInNodeReward + verifierReward;

        emit Mint(userAddr, userReward);
        emit Mint(checkInNode, checkInNodeReward);
        emit Mint(verifierNode, verifierReward);
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0) && to != address(0), "Invalid address");
        require(powerBalance[from] >= amount, "Insufficient power");

        powerBalance[from] -= amount;
        powerBalance[to] += amount;

        emit Transfer(from, to, amount);
    }
}

contracts/V1/StakeController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

interface IPowerAsset {
    function transfer(address to, uint256 amount) external;

    function transferFrom(address from, address to, uint256 amount) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function nodeList() external view returns (address[] memory);
}

interface IAiverseCoin {
    function getMintAmountByDay(uint256 day) external view returns (uint256);

    function userClaimToken(address userAddr, uint256 amount) external;
}

contract StakeController is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    struct StakeInfo {
        uint256 power;
        uint256 lastSettledDay;
        uint256 unclaimedReward;
    }

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _STAKE_TYPEHASH =
        keccak256(
            "Stake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _UNSTAKE_TYPEHASH =
        keccak256(
            "Unstake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _CLAIM_TYPEHASH =
        keccak256(
            "Claim(address userAddr,address node,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public constant MINE_REWARD_PERCENTAGE = 90;
    uint256 constant NODE_REWARD_COEF = 20;
    uint256 constant USER_REWARD_COEF = 80;
    uint256 public constant MAX_DAYS_FOR_REWARD = 7;

    mapping(address => uint256) public nonces;
    mapping(uint256 => uint256) public rewardPerPower;
    mapping(address => uint256) public nodeTotalPower;
    mapping(address => uint256) public nodeLastSettledDay;
    mapping(uint256 => uint256) public totalPowerSnapshot;
    mapping(uint256 => mapping(address => uint256))
        public nodeTotalPowerSnapshot;
    mapping(address => mapping(address => StakeInfo)) public userStakeInfo;
    mapping(address => address[]) public userStakedNodes;

    uint256 public currentSnapshotDay;
    uint256 public totalPower;
    address public aicoinAddr;
    address public powerAssetAddr;
    address public nodeManagerAddr;

    event Staked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event Unstaked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event UserClaimReward(
        address indexed userAddr,
        address indexed node,
        uint256 reward
    );
    event NodeClaimReward(address indexed node, uint256 reward);

    function initialize(
        address _aicoinAddr,
        address _powerAssetAddr,
        address _nodeManagerAddr
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-Stake-Controller", "1");
        __ReentrancyGuard_init();

        aicoinAddr = _aicoinAddr;
        powerAssetAddr = _powerAssetAddr;
        nodeManagerAddr = _nodeManagerAddr;
    }

    function version() public pure returns (string memory) {
        return "1.0.0";
    }

    function stake(address node, uint256 amount) external nonReentrant {
        _stake(msg.sender, node, amount);
        IPowerAsset(powerAssetAddr).transfer(address(this), amount);
    }

    function stakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _STAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _stake(userAddr, node, amount);

        IPowerAsset(powerAssetAddr).transferFrom(
            userAddr,
            address(this),
            amount
        );
    }

    function unstake(address node, uint256 amount) external nonReentrant {
        _unstake(msg.sender, node, amount);
        IPowerAsset(powerAssetAddr).transfer(msg.sender, amount);
    }

    function unstakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _UNSTAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _unstake(userAddr, node, amount);

        IPowerAsset(powerAssetAddr).transferFrom(
            address(this),
            userAddr,
            amount
        );
    }

    function nodeClaimReward() external nonReentrant {
        _checkIsNode(msg.sender);
        _nodeClaimReward(msg.sender);
    }

    function userClaimReward(address node) external nonReentrant {
        _userClaimReward(msg.sender, node);
    }

    function userClaimRewardWithSig(
        address userAddr,
        address node,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant {
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _CLAIM_TYPEHASH,
                userAddr,
                node,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _userClaimReward(userAddr, node);
    }

    function dailySettle() external onlyOwner nonReentrant {
        uint256 currentDay = _getCurrentDay();
        require(currentDay == currentSnapshotDay, "Already Snapshot today");
        totalPowerSnapshot[currentDay] = totalPower;
        uint256 totalReward = IAiverseCoin(aicoinAddr).getMintAmountByDay(
            currentDay
        );

        uint256 mineReward = (totalReward * MINE_REWARD_PERCENTAGE) / 100;
        uint256 foundationReward = totalReward - mineReward;
        _transferToken(INodeManager(nodeManagerAddr).owner(), foundationReward);

        address[] memory allNodes = INodeManager(nodeManagerAddr).nodeList();
        for (uint i = 0; i < allNodes.length; i++) {
            address node = allNodes[i];
            nodeTotalPowerSnapshot[currentDay][node] = nodeTotalPower[node];
        }

        uint256 unitReward = (mineReward * 1e18) / totalPower;
        rewardPerPower[currentDay] = unitReward;

        currentSnapshotDay = currentDay;
    }

    function _stake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");
        require(totalPower > 0, "No power staked");

        bool isNewStake = true;
        for (uint i = 0; i < userStakedNodes[userAddr].length; i++) {
            if (userStakedNodes[userAddr][i] == node) {
                isNewStake = false;
                break;
            }
        }
        if (isNewStake) {
            userStakedNodes[userAddr].push(node);
        }

        uint256 currentDay = _getCurrentDay();
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power += amount;
        nodeTotalPower[node] += amount;
        totalPower += amount;

        emit Staked(userAddr, node, amount);
    }

    function _unstake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");
        require(
            userStakeInfo[userAddr][node].power >= amount,
            "Insufficient staked amount"
        );

        uint256 currentDay = _getCurrentDay();
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power -= amount;
        nodeTotalPower[node] -= amount;
        totalPower -= amount;

        emit Unstaked(userAddr, node, amount);
    }

    function _nodeClaimReward(address node) internal {
        uint256 currentDay = _getCurrentDay();
        uint256 lastSettledDay = nodeLastSettledDay[node];

        uint256 reward = 0;
        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = (currentDay - MAX_DAYS_FOR_REWARD >
                lastSettledDay)
                ? currentDay - MAX_DAYS_FOR_REWARD
                : lastSettledDay;
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                uint256 powerSnapShot = nodeTotalPowerSnapshot[day][node];
                reward +=
                    ((rewardPerUnit * powerSnapShot) * NODE_REWARD_COEF) /
                    100 /
                    1e18;
            }
        }

        require(reward > 0, "No rewards available");

        nodeLastSettledDay[node] = currentDay;

        _transferToken(node, reward);
        emit NodeClaimReward(node, reward);
    }

    function _userClaimReward(address userAddr, address node) internal {
        StakeInfo storage info = userStakeInfo[userAddr][node];

        if (info.power > 0) {
            uint256 currentDay = _getCurrentDay();
            _settleUserPendingRewards(userAddr, node, currentDay);
        }

        uint256 reward = info.unclaimedReward;
        require(reward > 0, "No rewards available");

        info.unclaimedReward = 0;

        _transferToken(userAddr, reward);
        emit UserClaimReward(userAddr, node, reward);
    }

    function _transferToken(address to, uint256 amount) internal {
        IAiverseCoin(aicoinAddr).userClaimToken(to, amount);
    }

    function _settleUserPendingRewards(
        address userAddr,
        address node,
        uint256 currentDay
    ) internal {
        StakeInfo storage stakeInfo = userStakeInfo[userAddr][node];
        uint256 lastSettledDay = stakeInfo.lastSettledDay;
        uint256 reward = _calculateReward(
            stakeInfo.power,
            lastSettledDay,
            currentDay
        );
        if (reward > 0) {
            stakeInfo.unclaimedReward += reward;
            stakeInfo.lastSettledDay = currentDay;
        }
    }

    function _calculateReward(
        uint256 power,
        uint256 lastSettledDay,
        uint256 currentDay
    ) internal view returns (uint256) {
        uint256 totalReward = 0;

        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = (currentDay - MAX_DAYS_FOR_REWARD >
                lastSettledDay)
                ? currentDay - MAX_DAYS_FOR_REWARD
                : lastSettledDay;
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                totalReward +=
                    ((rewardPerUnit * power) * USER_REWARD_COEF) /
                    100 /
                    1e18;
            }
        }
        return totalReward;
    }

    function _getCurrentDay() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    function _checkIsNode(address addr) internal view {
        require(INodeManager(nodeManagerAddr).isNode(addr), "Invalid Caller");
    }

    function _checkSigExpire(uint256 expireAt) internal view {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );
    }
}

